package com.synexia.m3.bootstrap; import java.util.Set; import org.openrewrite.*; import org.openrewrite.java.JavaIsoVisitor; import org.openrewrite.java.tree.J; public final class M3BootstrapInventoryRecipe extends Recipe { private final Atoms atoms=new Atoms(this); public String getDisplayName(){return "M3 bootstrap atom/pattern inventory";} public String getDescription(){return "Read-only class/method atom inventory before repository-specific mutation recipes.";} public Set<String> getTags(){return Set.of("synexia","m3","recipe-first","bootstrap","read-only");} public int maxCycles(){return 1;} public TreeVisitor<?,ExecutionContext> getVisitor(){return new JavaIsoVisitor<ExecutionContext>(){String owner=""; public J.ClassDeclaration visitClassDeclaration(J.ClassDeclaration c,ExecutionContext x){String p=owner;owner=c.getSimpleName();row(x,"TYPE",owner,c.getKind().toString(),c.getBody().getStatements().size());J.ClassDeclaration r=super.visitClassDeclaration(c,x);owner=p;return r;} public J.MethodDeclaration visitMethodDeclaration(J.MethodDeclaration m,ExecutionContext x){row(x,"METHOD",owner+"#"+m.getSimpleName(),"arity",m.getParameters().size());return super.visitMethodDeclaration(m,x);} void row(ExecutionContext x,String k,String i,String s,int a){J.CompilationUnit u=getCursor().firstEnclosing(J.CompilationUnit.class);atoms.insertRow(x,new Atom(u==null?"":u.getSourcePath().normalize().toString(),k,i,s,a));}};} public boolean mutationAuthority(){return false;} static final class Atoms extends DataTable<Atom>{Atoms(Recipe r){super(r,"M3 bootstrap atoms","Read-only structural atoms.");}} public static final class Atom{@Column(displayName="Source",description="Source.") final String source; @Column(displayName="Kind",description="Kind.") final String kind; @Column(displayName="Identity",description="Identity.") final String identity; @Column(displayName="Shape",description="Shape.") final String shape; @Column(displayName="Arity",description="Arity.") final int arity; Atom(String s,String k,String i,String h,int a){source=s;kind=k;identity=i;shape=h;arity=a;} public String getSource(){return source;} public String getKind(){return kind;} public String getIdentity(){return identity;} public String getShape(){return shape;} public int getArity(){return arity;}} }